% Returns the second derivatives of the friction law F and state evolution G
% involving the parameters p and q, needed for Hessian computations:
%   F_V_p, F_Psi_p, G_V_p, G_Psi_p  -- mixed derivatives in the state variables and p
%   F_p_q, G_p_q                    -- second derivatives in the parameters p and q
% The functions are generated by generateFunctions.
function [F_V_p, F_Psi_p, G_V_p, G_Psi_p, F_p_q, G_p_q] = getSecondPartialDerivativeFuns(p, q)
    params = {'sigma0', 'a', 'b', 'f0', 'V0', 'D_c', 'tau0'};
    i_p = find(strcmp(params, p));
    i_q = find(strcmp(params, q));
    if isempty(i_p)
        error('Parameter %s not supported.', p);
    end
    if isempty(i_q)
        error('Parameter %s not supported.', q);
    end

    pkg = 'elastic.friction.inversion.';
    F_V_p = str2func([pkg 'F_V_' p]);
    F_Psi_p = str2func([pkg 'F_Psi_' p]);
    G_V_p = str2func([pkg 'G_V_' p]);
    G_Psi_p = str2func([pkg 'G_Psi_' p]);

    % Pairs are generated in the order of params, e.g. F_a_b but not F_b_a
    pq = params(sort([i_p, i_q]));
    F_p_q = str2func(sprintf('%sF_%s_%s', pkg, pq{:}));
    G_p_q = str2func(sprintf('%sG_%s_%s', pkg, pq{:}));
end
